{
  "findings": [
    {
      "ref": "[D529]",
      "area": "money",
      "claim": "A parent reports that the FTC’s Fortnite refund stopped taking claims on July 9, 2025, so any invitation to file now is fake.",
      "stance": "risk",
      "quote": "Claims closed July 9, 2025. In June 2025 the FTC sent 969,173 payments totaling more than $126 million. Its page still says: “We expect to send additional payments in 2026 after we have reviewed and validated all claims.” As of September 30, 2026 it gives no date and still carries a July 2025 date stamp. If you filed after February 14, 2025, the FTC says you do not need to do anything else right now while it reviews claims."
    },
    {
      "ref": "[D529]",
      "area": "money",
      "claim": "A parent reports that the FTC never demands money for refunds, and any message offering a share of an Apple or Google ruling is invented.",
      "stance": "risk",
      "quote": "The FTC never demands money; the refund administrator’s number is 1-833-915-0880. Free V-Bucks or an “App Store refund” from the court cases are invented."
    },
    {
      "ref": "[D529]",
      "area": "data",
      "claim": "A parent reports that the FTC settlement required Epic to turn voice and text chat off by default for children and teens.",
      "stance": "mitigation",
      "quote": "The settlement also required Epic to turn voice and text chat off by default for children and teens."
    },
    {
      "ref": "[D529]",
      "area": "age_gating",
      "claim": "A parent reports that the Dutch claim is brought by Stichting Massaschade & Consument (SMC) and represents Dutch players who played Fortnite before age 21, but it does not cover U.S. players.",
      "stance": "neutral",
      "quote": "The claim is brought by Stichting Massaschade & Consument (SMC), which says it will go to court if talks with Epic fail. It represents Dutch players who played Fortnite before age 21."
    },
    {
      "ref": "[D529]",
      "area": "developer_record",
      "claim": "A parent reports that Epic agreed to pay $520 million, including a $245 million refund order and a $275 million COPPA penalty, after the FTC found dark patterns and illegal data collection from children.",
      "stance": "risk",
      "quote": "Epic agreed to pay $520 million: a $245 million refund order and a $275 million COPPA penalty. The FTC alleged that Epic used design tricks known as dark patterns to charge players for purchases they did not want, let children run up charges without a parent’s permission, and locked some accounts after players disputed charges. Separately, the FTC alleged that Epic collected personal information from children under 13 without parental consent."
    }
  ]
}
